    echo "✅ No duplicate identifiers."
  fi
fi

echo "--> Step 2: Missing Electron Mocks Check"
if [ -d packages/main/src ]; then
  # Match both vi.mock('electron'...) and vi.doMock('electron'...) — doMock is required
